-- 2900 (release 47, photo standard r48.1): every car, every standard angle, generated by Gemini from references.
-- The owner (Nov 14): "Why is the background dealership still so fake looking? ... generate AI photos of every single car in
-- every single correct angle by sending Gemini a prompt with the sample photos as a reference and the real photos also as a
-- reference and the background as a reference and describing what we want the outcome to look like for each angle."
-- Then: a car with no listing photos (or too few to show what it is) uses its check-in and check-out photos as references.
--
--   1. vehicle_photos.r48: a row of the car's r48 set (ai_generated, one per standard angle: front three-quarter, front, side
--      profile, rear three-quarter, rear, dashboard, front seats, rear seats, trunk). Made by job photo_r45 with input
--      r45.mode 'r48' (the worker: features/listing/r48.ts, worker.ts makeR48), so 2840's filing applies: passed is
--      approved and on the site; refused is made again twice with the check's reasons as feedback; then flagged and kept
--      off the site, and the car's real photo of that angle stays on the site (2890).
--   2. The references (listing_job_context, fresh on every try): up to 6 of the car's real listing photos (the same angle
--      first); when it has fewer than 3, or none on the same side (outside or inside) as the angle, its newest check-in,
--      check-out and field job photos (condition_report_photos) fill up the list. Those are read by the worker only: never
--      a vehicle_photos row, never on the site. Then the composition guide of the angle for the car's body type, the stock
--      photo of the model, and for an outside angle the background plate of its family.
--   3. listing_r48_plates: the background plates (front, side, rear): made once by Gemini and checked "looks like a real
--      photo" (web/scripts/r48-references.mjs, or the worker on first need), replaceable by an Admin upload (Program
--      settings, Showroom background plates).
--   4. The gallery: a car's r48 photo of an angle is shown in place of its other photos of that angle; the angles without a
--      passed r48 photo show what they showed before. No real photo is taken off the site (is_public is never changed on a
--      real photo); every real photo stays in the car's record and the Admin view. The r48 front three-quarter is the cover.
--   5. app.job_photo_r48 every 5 minutes (listing_photo_r48_auto, on by default): the front three-quarter of every car first,
--      newest listed first, then the other angles; within Gemini's daily limit less the reserve (2000 a day by default: the
--      fleet of about 100 cars x 9 angles with retries fits in about a day). The r45 fleet remake is switched off (its
--      edited photos are what looked fake; new uploads still go through it).
set local check_function_bodies = off;

create function pg_temp.copy_grants(p_new regprocedure, p_old regprocedure) returns void
language plpgsql as $$
declare g text;
begin
  execute format('revoke all on function %s from public, anon, authenticated', p_new);
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, p_old, 'execute') then execute format('grant execute on function %s to %I', p_new, g); end if;
  end loop;
end $$;
create function pg_temp.patch_fn(p_sig regprocedure, p_old text, p_new text) returns void
language plpgsql as $$
declare d text := pg_get_functiondef(p_sig);
begin
  if position(p_old in d) = 0 then raise exception '2900: the text to change was not found in %: %', p_sig, left(p_old, 160); end if;
  execute replace(d, p_old, p_new);
end $$;

-- ================================================================ 1. the column, the settings, the plates
alter table vehicle_photos add column if not exists r48 boolean not null default false;
comment on column vehicle_photos.r48 is 'One of the car''s r48 set (2900): a standard angle generated by Gemini from the car''s real photos (or its check-in and check-out photos), the composition guide, the stock photo and the background plate. Always ai_generated.';
create index if not exists vehicle_photos_r48 on vehicle_photos (vehicle_id, shot_type) where r48 and replaced_at is null;

alter table program_settings add column if not exists listing_photo_r48_auto boolean not null default true;
comment on column program_settings.listing_photo_r48_auto is 'Listing photos (2900): every car''s nine standard angles generated by Gemini from references (r48.1), every 5 minutes, the front three-quarter of every car first, newest listed first, within the daily limit.';
alter table program_settings alter column listing_photo_r45_auto set default false;
update program_settings set listing_photo_r45_auto = false where listing_photo_r45_auto;
comment on column program_settings.listing_photo_r45_auto is 'Listing photos (2840): the r45 remake of every real photo. Off since 2900: the r48 generated set replaced it (new uploads are still made by Gemini as they arrive).';

create table if not exists listing_r48_plates (
  id uuid not null default gen_random_uuid() unique,
  family text primary key check (family in ('front', 'side', 'rear')),
  path text not null check (path ~ '^site/r48/plates/[a-z0-9-]+\.(jpg|png)$'),
  source text not null check (source in ('gemini', 'admin')),
  model text check (model is null or length(model) <= 80),
  "check" jsonb check ("check" is null or jsonb_typeof("check") = 'object'),
  made_by uuid references users (id),
  made_at timestamptz not null default now()
);
comment on table listing_r48_plates is 'The background plates of the r48 photos (2900): one empty showroom per angle family (front: front three-quarter and front; side; rear: rear three-quarter and rear), made by Gemini and checked as a real photo, or a real showroom photo an Admin uploaded.';
alter table listing_r48_plates enable row level security;
create policy admin_all on listing_r48_plates for all to authenticated using (app.is_admin()) with check (app.is_admin());
revoke all on listing_r48_plates from anon, authenticated;
grant select on listing_r48_plates to authenticated;
grant all on listing_r48_plates to service_role;
-- a setting an Admin changes: audited like the showroom rooms (2426)
create trigger audit_listing_r48_plates after insert or update or delete on listing_r48_plates for each row execute function app.audit_row();

-- ================================================================ 2. what the r45 machinery no longer touches
-- an r48 row is not an r45 photo (not remade, not counted, not a source of an r45 view)
select pg_temp.patch_fn('app.photo_r45_applies(vehicle_photos)'::regprocedure, 'select ph.replaced_at is null and', 'select not ph.r48 and ph.replaced_at is null and');
-- a real photo of an angle replaces an r45 view of it, never the r48 one (that is made from the real photos)
select pg_temp.patch_fn('app.vehicle_photo_r45_real()'::regprocedure, 'and x.ai_generated and x.replaced_at is null', 'and x.ai_generated and not x.r48 and x.replaced_at is null');
-- a new upload of an angle replaces the car's earlier photos of it (0022), never its r48 view, and the r48 view does not count
-- toward the angle's most photos
select pg_temp.patch_fn('app.record_listing_upload_0022(uuid, uuid, jsonb)'::regprocedure,
  'ph.shot_type = s.code and ph.replaced_at is null and ph.status <> ''rejected'';', 'ph.shot_type = s.code and ph.replaced_at is null and ph.status <> ''rejected'' and not ph.r48;');
select pg_temp.patch_fn('app.record_listing_upload_0022(uuid, uuid, jsonb)'::regprocedure,
  'where vehicle_id = i.vehicle_id and shot_type = s.code and replaced_at is null;', 'where vehicle_id = i.vehicle_id and shot_type = s.code and replaced_at is null and not r48;');
-- the car's primary photo (the cover mark): its passed r48 front three-quarter first
select pg_temp.patch_fn('app.primary_photo(uuid)'::regprocedure, 'ph.processed_path is not null) desc, ph.is_cover desc', 'ph.processed_path is not null) desc, ph.r48 desc, ph.is_cover desc');

-- ================================================================ 3. the standard and its references
create function app.photo_r48_spec() returns text language sql immutable parallel safe as $$ select 'r48.1'::text $$;
comment on function app.photo_r48_spec() is 'The r48 photo standard (2900), equal to R48_SPEC in web/src/features/listing/r48.ts.';

create function app.photo_r48_family(p_shot text) returns text language sql immutable parallel safe as $$
  select case when p_shot in ('front_left', 'front') then 'front' when p_shot = 'left' then 'side' when p_shot in ('rear_left', 'rear') then 'rear' end
$$;
-- the sample cars' drawing of the angle (features/car/studio.ts SHOTS), as r48.ts R48_ANGLES.guide
create function app.photo_r48_guide(p_vehicle uuid, p_shot text) returns text
language sql stable security definer set search_path = public, app as $$
  select 'site/r48/guides/' || coalesce(app.sample_body_key(p_vehicle), 'sedan') || '-' || g || '.jpg'
    from (select case p_shot when 'front_left' then 'lead' when 'front' then 'front' when 'left' then 'side' when 'rear_left' then 'rear34' when 'rear' then 'rear'
                             when 'dashboard' then 'dash' when 'front_seats' then 'seats' end as g) x
   where g is not null
$$;
create function app.photo_r48_slug(p text) returns text language sql immutable parallel safe as $$
  select nullif(btrim(regexp_replace(lower(coalesce(p, '')), '[^a-z0-9]+', '-', 'g'), '-'), '')
$$;
-- the stock photo of the model (vehicle_stock_photos, its largest stored width); the generation's year first
create function app.photo_r48_stock(p_vehicle uuid) returns text
language sql stable security definer set search_path = public, app as $$
  select s.path || '-' || (select max(z) from unnest(s.sizes) z) || '.webp'
    from vehicles v join vehicle_stock_photos s on s.kind = 'model' and s.status = 'active' and s.path is not null and cardinality(s.sizes) > 0
     and s.make = app.photo_r48_slug(v.make) and (app.photo_r48_slug(v.model) = s.model or app.photo_r48_slug(v.model) like s.model || '-%')
   where v.id = p_vehicle
   order by (v.year between s.year_from and s.year_to) desc nulls last, s.score desc nulls last, s.id
   limit 1
$$;

-- the shots of a check-in or check-out photo as listing shots (the clearest views; no close-ups, keys or documents)
create function app.photo_r48_handover_shot(p_shot text, p_angle text) returns text language sql immutable parallel safe as $$
  select case when coalesce(p_angle, p_shot) in ('front_left', 'front', 'left', 'rear_left', 'rear', 'front_right', 'right', 'rear_right', 'front_seats', 'rear_seats', 'trunk')
              then coalesce(p_angle, p_shot)
              when coalesce(p_angle, p_shot) in ('instrument_cluster', 'dashboard') then 'dashboard'
              when coalesce(p_angle, p_shot) like 'wheel\_%' then 'wheel' end
$$;

-- The references of one angle: [{bucket, path, shot, from}] in the order sent. The car's real listing photos first (the same
-- angle, then the same side of the car, then the rest; at most 6). When it has fewer than 3, or none on the angle's side,
-- its newest check-in, check-out and field job photos fill the list (the same angle first, outside views before close-ups).
create function app.photo_r48_refs(p_vehicle uuid, p_shot text) returns jsonb
language sql stable security definer set search_path = public, app as $$
  with real as (
    select ph.original_path as path, ph.shot_type as shot, ph.created_at,
           (ph.shot_type = p_shot) as same, (app.photo_is_exterior(ph.shot_type) = app.photo_is_exterior(p_shot)) as side
      from vehicle_photos ph join listing_shot_types st on st.code = ph.shot_type and st.is_public
     where ph.vehicle_id = p_vehicle and not ph.ai_generated and ph.replaced_at is null and ph.status <> 'rejected' and nullif(ph.original_path, '') is not null),
  need as (select count(*) < 3 or not bool_or(side) as more from real),
  hand as (
    select p.storage_bucket as bucket, p.storage_path as path, app.photo_r48_handover_shot(p.shot, p.angle) as shot, r.performed_at
      from condition_reports r join condition_report_photos p on p.condition_report_id = r.id
     where r.vehicle_id = p_vehicle and app.photo_r48_handover_shot(p.shot, p.angle) is not null and nullif(p.storage_path, '') is not null),
  pick as (
    (select 'vehicle-originals' as bucket, path, shot, 'listing' as src, 0 as grp,
            row_number() over (order by same desc, side desc, app.photo_rank(shot), created_at desc, path) as k from real)
    union all
    (select bucket, path, shot, 'handover', 1,
            row_number() over (order by shot = p_shot desc, (app.photo_is_exterior(shot) = app.photo_is_exterior(p_shot)) desc, (shot = 'wheel'), performed_at desc,
                               app.photo_rank(shot), path)
       from hand where (select more from need)))
  select coalesce(jsonb_agg(jsonb_build_object('bucket', bucket, 'path', path, 'shot', shot, 'from', src) order by grp, k), '[]'::jsonb)
    from (select * from pick order by grp, k limit 6) x
$$;

-- the car's listing (the job runs on one): the newest; a car photographed only at handovers gets one, not published
create function app.photo_r48_intake(p_vehicle uuid) returns uuid
language plpgsql security definer set search_path = public, app as $$
declare v uuid := app.photo_r45_intake(p_vehicle);
begin
  if v is not null then return v; end if;
  insert into listing_intakes (vehicle_id, started_role, state, review_required, notes)
  values (p_vehicle, 'admin', 'approved', false, 'Made by the photo standard (r48): the car''s photos are generated from its check-in and check-out photos.')
  returning id into v;
  return v;
end $$;

-- ================================================================ 4. queueing one angle
-- an angle of a car to the r48 standard: its r48 row made (or, asked again, queued again; the version on the site stays
-- until the new one passes). null when the car has no reference or the angle is being made.
create function app.photo_r48_queue(p_by uuid, p_vehicle uuid, p_shot text, p_force boolean default false) returns uuid
language plpgsql security definer set search_path = public, app as $$
declare ph vehicle_photos; v_refs jsonb; v_intake uuid; v_orig text; v_input jsonb;
begin
  if not (p_shot = any (app.photo_r45_angles())) then return null; end if;
  if coalesce((select v.is_sample from vehicles v where v.id = p_vehicle), true) then return null; end if;
  select * into ph from vehicle_photos where vehicle_id = p_vehicle and r48 and shot_type = p_shot and replaced_at is null order by created_at desc limit 1 for update;
  -- made or flagged: kept unless asked again; queued with no step left (a step cancelled or lost): queued again
  if ph.id is not null and not p_force and coalesce(ph.r45 ->> 'state', '') in ('done', 'flagged') then return null; end if;
  if ph.id is not null and exists (select 1 from listing_jobs j where j.vehicle_photo_id = ph.id and j.kind = 'photo_r45' and j.status in ('queued', 'running')) then return null; end if;
  v_refs := app.photo_r48_refs(p_vehicle, p_shot);
  if jsonb_array_length(v_refs) = 0 then return null; end if;
  v_intake := app.photo_r48_intake(p_vehicle);
  v_input := jsonb_build_object('r45', jsonb_build_object('mode', 'r48', 'car', app.photo_r45_car(p_vehicle), 'shot', p_shot), 'by', p_by);
  if ph.id is null then
    -- the original is the first listing photo it is made from (a check-in photo is in another bucket: a marker path)
    v_orig := coalesce((select e ->> 'path' from jsonb_array_elements(v_refs) e where e ->> 'from' = 'listing' limit 1), 'vehicles/original/r48/' || p_vehicle || '/' || p_shot || '.jpg');
    insert into vehicle_photos (vehicle_id, intake_id, angle, shot_type, original_path, status, is_public, background_status, ai_generated, r48, sort_order, scene, r45, uploaded_by)
    values (p_vehicle, v_intake, p_shot, p_shot, v_orig, 'processing', false, 'processing', true, true, -100 + coalesce(array_position(app.photo_r45_angles(), p_shot), 50),
            case when app.photo_is_exterior(p_shot) then 'showroom' end,
            jsonb_build_object('state', 'queued', 'spec', app.photo_r48_spec(), 'tries', 0, 'at', now()), p_by)
    returning * into ph;
  else
    update vehicle_photos set r45 = case when p_force or coalesce(ph.r45 ->> 'state', '') in ('redo', 'done', 'flagged')
                                         then coalesce(r45, '{}'::jsonb) - 'reasons' - 'why' || jsonb_build_object('state', 'queued', 'spec', app.photo_r48_spec(), 'tries', 0, 'at', now())
                                         else coalesce(r45, '{}'::jsonb) || jsonb_build_object('state', 'queued', 'at', now()) end,
           quality_flags = quality_flags - 'r45_flagged'
     where id = ph.id;
  end if;
  perform app.enqueue_listing_job(v_intake, 'photo_r45', ph.id, v_input);
  return ph.id;
end $$;

-- the cars the job takes, newest listed first: real cars with a listing photo or a check-in or check-out photo
create function app.photo_r48_cars() returns table (vehicle_id uuid, listed_at timestamptz)
language sql stable security definer set search_path = public, app as $$
  select v.id, coalesce((select max(i.created_at) from listing_intakes i where i.vehicle_id = v.id), v.created_at)
    from vehicles v
   where not v.is_sample
     and (exists (select 1 from vehicle_photos ph where ph.vehicle_id = v.id and not ph.ai_generated and ph.replaced_at is null and ph.status <> 'rejected')
          or exists (select 1 from condition_reports r join condition_report_photos p on p.condition_report_id = r.id
                      where r.vehicle_id = v.id and app.photo_r48_handover_shot(p.shot, p.angle) is not null))
   order by 2 desc, v.id
$$;

-- per car: how far its r48 set is (done, flagged, being made, of nine)
create function app.photo_r48_car(p_vehicle uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_build_object('angles', cardinality(app.photo_r45_angles()),
    'done', count(*) filter (where ph.r45 ->> 'state' = 'done'),
    'flagged', count(*) filter (where ph.r45 ->> 'state' = 'flagged'),
    'queued', count(*) filter (where ph.r45 ->> 'state' in ('queued', 'redo')),
    'handover_refs', exists (select 1 from jsonb_array_elements(app.photo_r48_refs(p_vehicle, 'front_left')) e where e ->> 'from' = 'handover'),
    'last_run', max((ph.r45 ->> 'at')::timestamptz))
    from vehicle_photos ph where ph.vehicle_id = p_vehicle and ph.r48 and ph.replaced_at is null
$$;
create function app.photo_r48_car_done(p_vehicle uuid) returns boolean
language sql stable security definer set search_path = public, app as $$
  select not exists (select 1 from unnest(app.photo_r45_angles()) a
                      where not exists (select 1 from vehicle_photos ph where ph.vehicle_id = p_vehicle and ph.r48 and ph.shot_type = a and ph.replaced_at is null
                                          and ph.r45 ->> 'state' in ('done', 'flagged')))
$$;

-- ================================================================ 5. the job (every 5 minutes)
create function app.job_photo_r48() returns text
language plpgsql security definer set search_path = public, app as $$
declare ps program_settings := app.settings(); v_room integer; r record; n integer := 0; v_pass integer; v_shot text; v_cars integer := 0; v_car boolean;
begin
  if not coalesce(ps.listing_photo_r48_auto, true) or not coalesce(ps.listing_showroom_ai, false) then return 'off'; end if;
  v_room := least(greatest(coalesce(ps.listing_photo_r45_batch, 12) - app.photo_r45_outstanding(), 0),
                  greatest(app.photo_gemini_left(coalesce(ps.listing_photo_r45_reserve, 50)) - app.photo_r45_outstanding(), 0));
  if v_room = 0 then return 'full or waiting for Gemini'; end if;
  -- the front three-quarter of every car first (the cover), then the other angles in the site's order
  for v_pass in 1..2 loop
    for r in select c.vehicle_id from app.photo_r48_cars() c loop
      exit when n >= v_room;
      v_car := false;
      foreach v_shot in array case when v_pass = 1 then array['front_left'] else (app.photo_r45_angles())[2:] end loop
        exit when n >= v_room;
        if app.photo_r48_queue(null, r.vehicle_id, v_shot, false) is not null then n := n + 1; v_car := true; end if;
      end loop;
      if v_car then v_cars := v_cars + 1; end if;
    end loop;
  end loop;
  return format('%s r48 view(s) queued (%s car step(s))', n, v_cars);
end $$;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.schedule('carmacars-photo-r48', '*/5 * * * *', 'select app.job_photo_r48()');
  end if;
end $$;

-- ================================================================ 6. the worker's context and answers
alter function app.listing_job_context(uuid) rename to listing_job_context_pre2900;
create function app.listing_job_context(p_job uuid) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare x jsonb := app.listing_job_context_pre2900(p_job); ph vehicle_photos; v_shot text; v_fam text;
begin
  if x is null or jsonb_typeof(x) <> 'object' or x ->> 'kind' <> 'photo_r45' or coalesce(x #>> '{input,r45,mode}', '') <> 'r48' then return x; end if;
  select * into ph from vehicle_photos where id = (select j.vehicle_photo_id from listing_jobs j where j.id = p_job);
  v_shot := coalesce(ph.shot_type, x #>> '{input,r45,shot}');
  v_fam := app.photo_r48_family(v_shot);
  return jsonb_set(x, '{input,r45}', (x #> '{input,r45}') || jsonb_strip_nulls(jsonb_build_object(
    'shot', v_shot, 'refs', app.photo_r48_refs(ph.vehicle_id, v_shot), 'family', v_fam,
    'plate', (select p.path from listing_r48_plates p where p.family = v_fam),
    'guide', app.photo_r48_guide(ph.vehicle_id, v_shot), 'stock', case when v_fam is not null then app.photo_r48_stock(ph.vehicle_id) end,
    'body', app.sample_body_key(ph.vehicle_id),
    'feedback', case when coalesce((ph.r45 ->> 'tries')::integer, 0) > 0 and jsonb_typeof(ph.r45 -> 'reasons') = 'array' then ph.r45 -> 'reasons' end)));
end $$;
select pg_temp.copy_grants('app.listing_job_context(uuid)'::regprocedure, 'app.listing_job_context_pre2900(uuid)'::regprocedure);

-- a plate the worker had to make (none was stored) is kept for every later photo of its family
alter function app.worker_listing_result(uuid, jsonb) rename to worker_listing_result_pre2900;
create function app.worker_listing_result(p_job uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare v jsonb := p #> '{output,r45,plate_made}';
begin
  if jsonb_typeof(v) = 'object' and v ->> 'family' in ('front', 'side', 'rear') and coalesce(v ->> 'path', '') ~ '^site/r48/plates/[a-z0-9-]+\.(jpg|png)$' then
    insert into listing_r48_plates (family, path, source, model, "check") values (v ->> 'family', v ->> 'path', 'gemini', left(v ->> 'model', 80), case when jsonb_typeof(v -> 'check') = 'object' then v -> 'check' end)
    on conflict (family) do nothing;
  end if;
  return app.worker_listing_result_pre2900(p_job, p);
end $$;
select pg_temp.copy_grants('app.worker_listing_result(uuid, jsonb)'::regprocedure, 'app.worker_listing_result_pre2900(uuid, jsonb)'::regprocedure);

-- ================================================================ 7. the gallery: the r48 photo of an angle in place of the others of it
alter function app.public_listing_photos(uuid) rename to public_listing_photos_pre2900;
create function app.public_listing_photos(p_vehicle uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  with a as (select coalesce(app.public_listing_photos_pre2900(p_vehicle), '[]'::jsonb) as arr),
       g as (select ph.shot_type, ph.processed_path from vehicle_photos ph
              where ph.vehicle_id = p_vehicle and ph.r48 and ph.replaced_at is null and ph.status = 'approved' and ph.is_public and ph.processed_path is not null)
  select case when not exists (select 1 from g) then a.arr
              else coalesce((select jsonb_agg(t.e order by t.n) from jsonb_array_elements(a.arr) with ordinality t(e, n)
                              where (t.e ->> 'path') in (select processed_path from g) or coalesce(t.e ->> 'shot', '') not in (select shot_type from g)), '[]'::jsonb) end
    from a
$$;
select pg_temp.copy_grants('app.public_listing_photos(uuid)'::regprocedure, 'app.public_listing_photos_pre2900(uuid)'::regprocedure);

-- ================================================================ 8. Admin: the Photo standard card, the redo, the plates
alter function app.photo_r45_fleet_read(uuid, jsonb) rename to photo_r45_fleet_read_pre2900;
create function app.photo_r45_fleet_read(p_by uuid, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare x jsonb := app.photo_r45_fleet_read_pre2900(p_by, p); ps program_settings := app.settings();
begin
  return x || jsonb_build_object('r48_spec', app.photo_r48_spec(), 'r48_auto', coalesce(ps.listing_photo_r48_auto, true) and coalesce(ps.listing_showroom_ai, false),
    'plates', (select count(*) from listing_r48_plates),
    'cars', coalesce((select jsonb_agg(coalesce(o.e, jsonb_build_object('id', c.vehicle_id, 'name', app.vehicle_name(c.vehicle_id), 'fleet_number', v.fleet_number,
                 'total', 0, 'at_standard', 0, 'generated', 0, 'flagged', 0, 'queued', 0, 'missing', 0, 'last_run', null, 'primary', app.vehicle_primary_state(c.vehicle_id), 'done', false))
               || jsonb_build_object('r48', app.photo_r48_car(c.vehicle_id), 'r48_done', app.photo_r48_car_done(c.vehicle_id)) order by c.listed_at desc, c.vehicle_id)
      from app.photo_r48_cars() c join vehicles v on v.id = c.vehicle_id
      left join lateral (select e from jsonb_array_elements(x -> 'cars') e where e ->> 'id' = c.vehicle_id::text) o on true), '[]'::jsonb));
end $$;
select pg_temp.copy_grants('app.photo_r45_fleet_read(uuid, jsonb)'::regprocedure, 'app.photo_r45_fleet_read_pre2900(uuid, jsonb)'::regprocedure);

-- Redo this car now: its r48 set made again too (the versions on the site stay until the new ones pass); Redo every car:
-- every r48 photo marked to be made again by the job
alter function app.photo_r45_redo(uuid, jsonb) rename to photo_r45_redo_pre2900;
create function app.photo_r45_redo(p_by uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare x jsonb := app.photo_r45_redo_pre2900(p_by, p); v_vehicle uuid := nullif(p ->> 'vehicle', '')::uuid; a text; n integer := 0;
begin
  if coalesce((p ->> 'all')::boolean, false) then
    update vehicle_photos set r45 = coalesce(r45, '{}'::jsonb) || jsonb_build_object('state', 'redo', 'tries', 0, 'at', now())
     where r48 and replaced_at is null and coalesce(r45 ->> 'state', '') not in ('queued', 'redo');
    get diagnostics n = row_count;
    perform app.job_photo_r48();
    return x || jsonb_build_object('r48_waiting', n);
  end if;
  if v_vehicle is not null then
    foreach a in array app.photo_r45_angles() loop
      if app.photo_r48_queue(p_by, v_vehicle, a, true) is not null then n := n + 1; end if;
    end loop;
    update listing_jobs set next_attempt_at = now() - interval '1 minute' where vehicle_id = v_vehicle and kind = 'photo_r45' and status = 'queued';
  end if;
  return x || jsonb_build_object('r48', n);
end $$;
select pg_temp.copy_grants('app.photo_r45_redo(uuid, jsonb)'::regprocedure, 'app.photo_r45_redo_pre2900(uuid, jsonb)'::regprocedure);

-- the plates (Program settings > Listings, Admin): read; set one from an upload ({family: front|side|rear|all, path}); clear
-- one ({family, clear: true}: Gemini makes it again on the next photo of its family)
create function app.photo_r48_plates(p_by uuid, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare f text := coalesce(p ->> 'family', ''); v_path text := p ->> 'path';
begin
  if p_by is null or not app.user_is_admin(p_by) then raise exception 'An Admin sets the showroom background plates' using errcode = '42501'; end if;
  if f <> '' then
    if f not in ('front', 'side', 'rear', 'all') then raise exception 'Unknown plate: front, side, rear or all' using errcode = '22023'; end if;
    if coalesce((p ->> 'clear')::boolean, false) then
      delete from listing_r48_plates where family = f or f = 'all';
    else
      if coalesce(v_path, '') !~ '^site/r48/plates/[a-z0-9-]+\.(jpg|png)$' then raise exception 'The plate''s file is not valid' using errcode = '22023'; end if;
      insert into listing_r48_plates (family, path, source, made_by, made_at)
      select x, v_path, 'admin', p_by, now() from unnest(case when f = 'all' then array['front', 'side', 'rear'] else array[f] end) x
      on conflict (family) do update set path = excluded.path, source = 'admin', model = null, "check" = null, made_by = p_by, made_at = now();
    end if;
  end if;
  return jsonb_build_object('plates', coalesce((select jsonb_agg(jsonb_build_object('family', l.family, 'path', l.path, 'source', l.source, 'made_at', l.made_at,
      'issues', l."check" -> 'issues') order by array_position(array['front', 'side', 'rear'], l.family)) from listing_r48_plates l), '[]'::jsonb));
end $$;

alter function app.door(uuid, text, text, text, jsonb) rename to door_pre2900;
create function app.door(p_user uuid, p_aal text, p_call text, p_name text, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
begin
  if (p_call = 'ops_read' and p_name = 'photo_r48_plates') or (p_call = 'ops_do' and p_name = 'photo_r48_plate') then
    perform app.door_begin(p_user, p_aal);
    return app.photo_r48_plates(p_user, case when p_call = 'ops_read' then '{}'::jsonb else coalesce(p, '{}'::jsonb) end);
  end if;
  return app.door_pre2900(p_user, p_aal, p_call, p_name, p);
end $$;
select pg_temp.copy_grants('app.door(uuid, text, text, text, jsonb)'::regprocedure, 'app.door_pre2900(uuid, text, text, text, jsonb)'::regprocedure);

-- ================================================================ privileges
do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'app' and p.proname = any (array['photo_r48_spec', 'photo_r48_family', 'photo_r48_guide', 'photo_r48_slug', 'photo_r48_stock', 'photo_r48_handover_shot',
              'photo_r48_refs', 'photo_r48_intake', 'photo_r48_queue', 'photo_r48_cars', 'photo_r48_car', 'photo_r48_car_done', 'job_photo_r48', 'photo_r48_plates',
              'listing_job_context_pre2900', 'worker_listing_result_pre2900', 'public_listing_photos_pre2900', 'photo_r45_fleet_read_pre2900', 'photo_r45_redo_pre2900', 'door_pre2900'])
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    execute format('grant execute on function %s to service_role', f.sig);
  end loop;
end $$;
